*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS90032.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : btn_Calc
 * 설명       : 이자지급액 계산버튼
 * 계산로직 : (초일 산입, 말일 불산입)
 * [CASE 최초] 상장금액 X 표면이자율 X (최초이자지급일 - 발행일) / 단수일이자기준
 * [CASE 중간] 상장금액 X 표면이자율 X (이자계산주기 / 12)
 * [CASE 최종] 상장금액 X 표면이자율 X (마지막차수 이자지급일 - 마지막 전회차 이자지급일) / 단수일이자기준
 ***********************************************/
scwin.btn_Calc = function() {
    // 이자지급액 초기화
    $c.stf.setObjectValue(edt_PrincPayAmt, "");

    // 계산전 검증
    if (!scwin.fn_CheckValidation()) {
        return;
    }
    var bndOddllotddIntBas = 0;
    // 단수일 이자기준 구하기, 코드를 값으로 변경
    if ($c.stf.getObjectValue(txb_BndOddllotddIntBasTpCd) == "1") {
        bndOddllotddIntBas = 360;
    } else if ($c.stf.getObjectValue(txb_BndOddllotddIntBasTpCd) == "2") {
        bndOddllotddIntBas = 365;
    } else if ($c.stf.getObjectValue(txb_BndOddllotddIntBasTpCd) == "3") {
        bndOddllotddIntBas = 366;
    }
    var rdoParam = $c.stf.getObjectValue(rdo_PARAM); //라디오 선택값
    var listAmt = $c.stf.getObjectValue(edt_ListAmt); //상장금액
    var coupnRt = $c.stf.getObjectValue(edt_CoupnRt); //표면이자율
    var fstIntPayDd = $c.stf.getObjectValue(edt_FstIntPayDd); //최초이자지급일
    var isuDd = $c.stf.getObjectValue(edt_IsuDd); //발행일
    var intPayCalcMms = $c.stf.getObjectValue(edt_IntPayCalcMms); //이자계산주기

    // 최초 이자계산
    if (rdoParam == "F") {
        //(최초이자지급일 - 발행일) 날짜 차이 계산 (일 단위)
        var timeDiff = $c.ut.cGetDifTodayInputdayBnd(fstIntPayDd, isuDd);
        calcIntPayAmt = (listAmt * (coupnRt * 100000) * (timeDiff / bndOddllotddIntBas)) / (100000 * 100);

        // 중간 이자계산

    } else if (rdoParam == "M") {
        calcIntPayAmt = (listAmt * (coupnRt * 100000) * (intPayCalcMms / 12)) / (100000 * 100);
    } else if (rdoParam == "L") {
        var lastIntPayDd = dts_List.getCellData(dts_List.getTotalRow(), 'INT_PAY_DD');
        var lastIntPayDd_1 = dts_List.getCellData(dts_List.getTotalRow() - 1, 'INT_PAY_DD');

        //(마지막차수 이자지급일 - 마지막 전회차 이자지급일) 날짜 차이 계산 (일 단위)
        var timeDiff = $c.ut.cGetDifTodayInputdayBnd(lastIntPayDd, lastIntPayDd_1);
        calcIntPayAmt = (listAmt * (coupnRt * 100000) * (timeDiff / bndOddllotddIntBas)) / (100000 * 100);
    }

    // 이자원단위 미만처리에따라 이자 보정..
    if ($c.stf.getObjectValue(txb_IntUdwonProcsCd) == "1") {
        // 절사
        calcIntPayAmt = Math.floor(calcIntPayAmt);
    } else if ($c.stf.getObjectValue(txb_IntUdwonProcsCd) == "2") {
        // 절상
        calcIntPayAmt = Math.ceil(calcIntPayAmt);
    } else if ($c.stf.getObjectValue(txb_IntUdwonProcsCd) == "3") {
        // 사사오입
        calcIntPayAmt = Math.round(calcIntPayAmt);
    } else if ($c.stf.getObjectValue(txb_IntUdwonProcsCd) == "4") {
        // 원미만인정

    }

    //결과값 표시
    $c.stf.setObjectValue(edt_PrincPayAmt, calcIntPayAmt);
};


/********************************************** 
 * 함수명   : fn_CheckValidation
 * 설명      : 이자계산전 검증
 ***********************************************/
scwin.fn_CheckValidation = function() {
    if ($c.stf.getObjectValue(rdo_PARAM) == "") {
        $c.win.alert("계산기준을 선택하세요.");
        rdo_PARAM.focus();
        return false;
    }

    // 고정금리-이표채 and 단수일이자기준 is not null인 경우만 최초,중간,최종 이자계산 가능.
    // else 중간만 계산 가능.
    // 단수일이자기준 : 1 - 360일 / 2 - 365일 / 3 - 366일 
    if ($c.stf.getObjectValue(rdo_PARAM) == "F" || $c.stf.getObjectValue(rdo_PARAM) == "L") {
        // 이자지급방법 : 13(고정금리-이표채), 단수일이자기준 : 2(365일)
        if ($c.stf.getObjectValue(txb_IntPayMethdCd) != "13") {
            $c.win.alert("[고정금리형-이표채]만 최초/최종 이자계산이 가능합니다.");
            return false;
        }
        if ($c.stf.getObjectValue(txb_BndOddllotddIntBasTpCd) == "") {
            $c.win.alert("단수일이자기준값이 없습니다.\n최초/최종 이자계산이 불가합니다.");
            return false;
        }
    }
    var rdoParam = $c.stf.getObjectValue(rdo_PARAM); //라디오 선택값
    var listAmt = $c.stf.getObjectValue(edt_ListAmt); //상장금액
    var coupnRt = $c.stf.getObjectValue(edt_CoupnRt); //표면이자율
    var fstIntPayDd = $c.stf.getObjectValue(edt_FstIntPayDd); //최초이자지급일
    var isuDd = $c.stf.getObjectValue(edt_IsuDd); //발행일
    var intPayCalcMms = $c.stf.getObjectValue(edt_IntPayCalcMms); //이자계산주기

    // 필수값 체크
    if (listAmt == "") {
        $c.win.alert("상장금액이 없습니다.");
        return false;
    }
    if (coupnRt == "") {
        $c.win.alert("표면이자율이 없습니다.");
        return false;
    }

    // 최초 이자계산
    if (rdoParam == "F") {
        if (isuDd == "") {
            $c.win.alert("발행일이 없습니다.");
            return false;
        }
        if (fstIntPayDd == "") {
            $c.win.alert("최초이자지급일이 없습니다.");
            return false;
        }

        // 중간 이자계산

    } else if (rdoParam == "M") {
        if (intPayCalcMms == "") {
            $c.win.alert("이자계산주기값이 없습니다.");
            return false;
        }
    } else if (rdoParam == "L") {
        if (dts_List.getTotalRow() < 2) {
            $c.win.alert("차수가 2개 미만인 경우 '최종' 이자계산이 불가합니다.");
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_Copy
 * 설명       : 원리금 정보를 복사한다.
 ***********************************************/
scwin.fn_Copy = function() {
    var prt = $c.frame.path("../");
    //copy (fromDataSet, toDataSet)
    $c.stf.CopyDataSet(prt.dts_Princint, dts_List);
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        $c.stf.setObjectValue(txb_BndMktactTpCd, arrPar[0].BND_MKTACT_TP_CD);
        $c.stf.setObjectValue(edt_ListAmt, arrPar[0].LIST_AMT);
        $c.stf.setObjectValue(edt_CoupnRt, arrPar[0].COUPN_RT);
        $c.stf.setObjectValue(edt_FstIntPayDd, arrPar[0].FST_INT_PAY_DD);
        $c.stf.setObjectValue(edt_IsuDd, arrPar[0].ISU_DD);
        $c.stf.setObjectValue(edt_IntPayCalcMms, arrPar[0].INT_PAY_CALC_MMS);
        $c.stf.setObjectValue(txb_IntPayMethdCd, arrPar[0].INT_PAY_METHD_CD);
        $c.stf.setObjectValue(txb_BndOddllotddIntBasTpCd, arrPar[0].BND_ODDLLOTDD_INT_BAS_TP_CD);
        $c.stf.setObjectValue(txb_IntUdwonProcsCd, arrPar[0].INT_UDWON_PROCS_CD);
    }
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(txb_BndMktactTpCd, false);
    $c.stf.showObj(edt_ListAmt, false);
    $c.stf.showObj(edt_CoupnRt, false);
    $c.stf.showObj(edt_FstIntPayDd, false);
    $c.stf.showObj(edt_IsuDd, false);
    $c.stf.showObj(edt_IntPayCalcMms, false);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Top);
    $c.bns.BnsPanelToGroupBox(panel_1);
    $c.bns.BnsPanelToGroupBox(panel_2);

    //호출파라미터설정
    scwin.fn_SetParam();

    //목록복사
    scwin.fn_Copy();

    // 기본값은 최종
    $c.stf.setObjectValue(rdo_PARAM, "L");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {

};
scwin.btn_Calc_onclick = function() {
    scwin.btn_Calc();
};
scwin.edt_ListAmt_OnKeyUp = function(keycode, skeycode) {
    $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan($c.stf.getObjectValue(edt_ListAmt)));
};
scwin.edt_ListAmt_OnKillFocus = function() {
    edt_ListAmt.RightMargin = 5;
};
scwin.edt_CoupnRt_OnKillFocus = function() {
    edt_CoupnRt.RightMargin = 5;
};
scwin.edt_IntPayCalcMms_OnKillFocus = function() {
    edt_IntPayCalcMms.RightMargin = 5;
};
scwin.edt_PrincPayAmt_OnKillFocus = function() {
    edt_PrincPayAmt.RightMargin = 5;
};
